from collections import Counter
from functools import lru_cache
P={1:800,2:1520,3:2160,4:2560,5:3000}
def canon(c):
    c=sorted(c,reverse=True)
    while len(c)<5: c.append(0)
    return tuple(c)
def dp(state):
    if sum(state)==0: return 0
    best=10**9
    for mask in range(1,32):
        r=list(state); s=0; ok=True
        for i in range(5):
            if mask&(1<<i):
                if state[i]<=0: ok=False; break
                r[i]-=1; s+=1
        if not ok: continue
        c=P[s]+dp(canon(tuple(r)))
        if c<best: best=c
    return best
# For each (g,S) with 5 distinct books available, what size multiset is optimal?
# We'll just look at savings = S*800 - cost
for g in range(1,7):
    for S in range(g, 5*g+1):
        # balanced-ish counts summing to S with max g and 5 distinct
        # construct counts: distribute S over 5 books, max = g
        counts=[]
        rem=S
        for i in range(5):
            v=min(g, rem)
            counts.append(v); rem-=v
        counts=canon(tuple(counts))
        if counts[0]!=g: continue
        cost=dp(counts)
        sav=S*800-cost
        print(f'g={g} S={S} counts={counts} cost={cost} savings={sav}')
" 2>&1 | head -60"}

