                r[i]-=1; s+=1
        if not ok: continue
        c=P[s]+dp(canon(tuple(r)))
        if c<best: best=c
    return best

# greedy: g groups, add books 2-5 (desc count) to groups with highest marginal benefit
marg={1:80,2:160,3:400,4:360}
