    counts=sorted(Counter(basket).values(),reverse=True)
    while len(counts)<5: counts.append(0)
    g=counts[0]
    if g==0: return 0
    sizes=[1]*g
    for i in range(1,5):
        c=counts[i]
        # pick c groups with highest marginal benefit
